# Reference standard errors for #936 from drmTMB (generated outputs only; no
# drmTMB source is copied). Run from the repository root with drmTMB installed:
#
#   Rscript --vanilla test/fixtures/vcov_unitfree_936/gen_drmtmb.R
#
# Writes test/fixtures/vcov_unitfree_936/expected_drmtmb.toml and
# expected_drmtmb.meta.toml. The data (data.csv) are written by Julia with
# StableRNG(20261016); see test/test_vcov_unitfree_936.jl.
suppressPackageStartupMessages(library(drmTMB))
dir <- file.path("test", "fixtures", "vcov_unitfree_936")
d0 <- read.csv(file.path(dir, "data.csv"))

cases <- list(
  uncentred      = data.frame(y = d0$y,       year = d0$year),
  centred        = data.frame(y = d0$y,       year = d0$year - 2000),
  y1e4_uncentred = data.frame(y = d0$y * 1e4, year = d0$year),
  y1e4_centred   = data.frame(y = d0$y * 1e4, year = d0$year - 2000)
)

fmt <- function(x) formatC(x, digits = 17, format = "g")
out <- c("# drmTMB reference fits for #936 (generated by gen_drmtmb.R; numbers only)")
for (nm in names(cases)) {
  fit <- drmTMB(bf(y ~ year, sigma ~ 1), family = gaussian(), data = cases[[nm]])
  V <- vcov(fit)
  cf <- unlist(coef(fit))   # mu then sigma, the order of rownames(V)
  out <- c(out, "", sprintf("[%s]", nm),
           sprintf("coef_names = [%s]", paste0('"', rownames(V), '"', collapse = ", ")),
           sprintf("coef = [%s]", paste(fmt(unname(cf)), collapse = ", ")),
           sprintf("se = [%s]", paste(fmt(sqrt(diag(V))), collapse = ", ")),
           sprintf("logLik = %s", fmt(as.numeric(logLik(fit)))),
           sprintf("converged = %s", tolower(as.character(isTRUE(is_converged(fit))))))
}
writeLines(out, file.path(dir, "expected_drmtmb.toml"))
writeLines(c(
  "# Provenance of expected_drmtmb.toml (no drmTMB code)",
  sprintf('drmTMB_version = "%s"', as.character(packageVersion("drmTMB"))),
  sprintf('TMB_version = "%s"', as.character(packageVersion("TMB"))),
  sprintf('R_version = "%s"', paste(R.version$major, R.version$minor, sep = ".")),
  'call = "drmTMB(bf(y ~ year, sigma ~ 1), family = gaussian(), data = d)"',
  sprintf('date = "%s"', format(Sys.Date()))
), file.path(dir, "expected_drmtmb.meta.toml"))
